import { MakeLogicType, actions, afterMount, connect, kea, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { aiGatewayDevTokensTeamUsageRetrieve } from '../generated/api'
import type { DevTeamUsageApi, DevTokenActivityApi, DevUserUsageApi } from '../generated/api.schemas'

export const PAGE_SIZE_OPTIONS = [10, 25, 50, 100]

function matches(search: string, ...values: (string | null | undefined)[]): boolean {
    return values.some((value) => value?.toLowerCase().includes(search))
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface devModeTeamUsageLogicValues {
    // teamLogic
    currentTeamId: number | null
    filteredActivity: DevTokenActivityApi[]
    filteredUsers: DevUserUsageApi[]
    isPayingTeam: boolean
    pageSize: number
    refusal: string | null
    search: string
    teamUsage: DevTeamUsageApi | null
    teamUsageLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface devModeTeamUsageLogicActions {
    loadTeamUsage: () => any
    loadTeamUsageFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadTeamUsageSuccess: (
        teamUsage: DevTeamUsageApi,
        payload?: any
    ) => {
        teamUsage: DevTeamUsageApi
        payload?: any
    }
    setPageSize: (pageSize: number) => {
        pageSize: number
    }
    setSearch: (search: string) => {
        search: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface devModeTeamUsageLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        isPayingTeam: (teamUsage: DevTeamUsageApi | null, currentTeamId: number | null) => boolean
        filteredUsers: (teamUsage: DevTeamUsageApi | null, search: string) => DevUserUsageApi[]
        filteredActivity: (teamUsage: DevTeamUsageApi | null, search: string) => DevTokenActivityApi[]
    }
}

export type devModeTeamUsageLogicType = MakeLogicType<
    devModeTeamUsageLogicValues,
    devModeTeamUsageLogicActions,
    Record<string, any>,
    devModeTeamUsageLogicMeta
>

export const devModeTeamUsageLogic = kea<devModeTeamUsageLogicType>([
    path(['products', 'ai_gateway', 'frontend', 'logics', 'devModeTeamUsageLogic']),
    connect(() => ({ values: [teamLogic, ['currentTeamId']] })),
    actions({
        setSearch: (search: string) => ({ search }),
        setPageSize: (pageSize: number) => ({ pageSize }),
    }),
    loaders({
        teamUsage: [
            null as DevTeamUsageApi | null,
            {
                loadTeamUsage: async () => {
                    try {
                        return await aiGatewayDevTokensTeamUsageRetrieve()
                    } catch (error: any) {
                        throw new Error(error?.detail || error?.message || "Couldn't load team usage.")
                    }
                },
            },
        ],
    }),
    reducers({
        refusal: [
            null as string | null,
            {
                loadTeamUsageFailure: (_, { error }) => error ?? null,
                loadTeamUsageSuccess: () => null,
            },
        ],
        search: ['', { setSearch: (_, { search }) => search }],
        pageSize: [PAGE_SIZE_OPTIONS[0], { setPageSize: (_, { pageSize }) => pageSize }],
    }),
    selectors({
        isPayingTeam: [
            (s) => [s.teamUsage, s.currentTeamId],
            (teamUsage: DevTeamUsageApi | null, currentTeamId: number | null): boolean =>
                !!teamUsage && teamUsage.paying_team_id === currentTeamId,
        ],
        filteredUsers: [
            (s) => [s.teamUsage, s.search],
            (teamUsage: DevTeamUsageApi | null, search: string): DevUserUsageApi[] => {
                const needle = search.trim().toLowerCase()
                const users = teamUsage?.users ?? []
                return needle ? users.filter((user) => matches(needle, user.email, user.distinct_id)) : users
            },
        ],
        filteredActivity: [
            (s) => [s.teamUsage, s.search],
            (teamUsage: DevTeamUsageApi | null, search: string): DevTokenActivityApi[] => {
                const needle = search.trim().toLowerCase()
                const activity = teamUsage?.activity ?? []
                return needle
                    ? activity.filter((entry) => matches(needle, entry.owner_email, entry.actor_email))
                    : activity
            },
        ],
    }),
    afterMount(({ actions }) => {
        actions.loadTeamUsage()
    }),
])
